@* Reusable message input: textarea + submit button *@

<div class="message-input-area">
    <textarea class="message-textarea"
              placeholder="@Placeholder"
              @bind="text"
              @onkeydown="HandleKeyDown"
              rows="2"></textarea>
    <button class="send-btn" @onclick="Submit" disabled="@string.IsNullOrWhiteSpace(text)">
        @ButtonText
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonText { get; set; } = "Send";
    [Parameter, EditorRequired] public EventCallback<string> OnSubmit { get; set; }

    private string text = string.Empty;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Submit();
        }
    }

    private async Task Submit()
    {
        if (string.IsNullOrWhiteSpace(text)) return;
        var content = text.Trim();
        text = string.Empty;
        await OnSubmit.InvokeAsync(content);
    }
}

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid var(--bs-border-color, #dee2e6);
    background: var(--bs-body-bg, #fff);
    align-items: flex-end;
}

.message-textarea {
    flex: 1;
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.9rem;
    resize: none;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-textarea:focus {
    border-color: var(--bs-primary, #6f42c1);
    box-shadow: 0 0 0 2px rgba(111, 66, 193, 0.15);
}

.send-btn {
    padding: 8px 20px;
    border: none;
    border-radius: 8px;
    background: var(--bs-primary, #6f42c1);
    color: #fff;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    white-space: nowrap;
    transition: opacity 0.15s;
}

.send-btn:hover:not(:disabled) {
    opacity: 0.85;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

@* Single message: author, timestamp, content, reactions, hover actions *@

<div class="message-item @(IsThreadRoot ? "thread-root" : "")"
     @onmouseenter="() => showActions = true"
     @onmouseleave="HideAll">

    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time" title="@Message.SentAt.ToString("f")">@FormatRelativeTime(Message.SentAt)</span>
    </div>

    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="reactions-row">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="reaction-badge" @onclick="() => OnReact.InvokeAsync(reaction.Emoji)"
                        title="@string.Join(", ", reaction.Users)">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync()">
            @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (showActions && ShowActions)
    {
        <div class="action-bar">
            <button class="action-btn" @onclick="() => OnOpenThread.InvokeAsync()" title="Reply in thread">
                💬 Reply
