@* Right panel: thread view with root message, replies, and reply input *@

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    <div class="thread-root-quote">
        <MessageItem Message="RootMessage" ShowActions="false" />
    </div>

    <div class="thread-divider">
        <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
    </div>

    <div class="thread-replies">
        @foreach (var reply in Replies)
        {
            <MessageItem Message="reply"
                         ShowActions="false"
                         OnReact="(emoji) => OnReactInThread.InvokeAsync((reply.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="Reply…"
                  ButtonText="Reply"
                  OnSubmit="OnSendReply" />
</div>

@code {
    [Parameter, EditorRequired] public Message RootMessage { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Replies { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnClose { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReactInThread { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: var(--bs-body-bg, #fff);
    border-left: 1px solid var(--bs-border-color, #dee2e6);
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: var(--bs-secondary-color, #6c757d);
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
    transition: background 0.15s;
}

.close-btn:hover {
    background: var(--bs-tertiary-bg, #f0f0f0);
    color: var(--bs-body-color, #212529);
}

.thread-root-quote {
    padding: 8px 0;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
    background: var(--bs-tertiary-bg, #f8f9fa);
    flex-shrink: 0;
}

.thread-divider {
    padding: 8px 16px;
    font-size: 0.8rem;
    color: var(--bs-secondary-color, #6c757d);
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

